function registerAdsApi(router::HTTP.Router, impl; path_prefix::String="", optional_middlewares...)
    HTTP.register!(router, "POST", path_prefix * "/ad_accounts/{ad_account_id}/ad_previews", OpenAPI.Servers.middleware(impl, ad_previews_create_read, ad_previews_create_validate, ad_previews_create_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/ad_accounts/{ad_account_id}/ads/targeting_analytics", OpenAPI.Servers.middleware(impl, ad_targeting_analytics_get_read, ad_targeting_analytics_get_validate, ad_targeting_analytics_get_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/ad_accounts/{ad_account_id}/ads/analytics", OpenAPI.Servers.middleware(impl, ads_analytics_read, ads_analytics_validate, ads_analytics_invoke; optional_middlewares...))
    HTTP.register!(router, "POST", path_prefix * "/ad_accounts/{ad_account_id}/ads", OpenAPI.Servers.middleware(impl, ads_create_read, ads_create_validate, ads_create_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/ad_accounts/{ad_account_id}/ads/{ad_id}", OpenAPI.Servers.middleware(impl, ads_get_read, ads_get_validate, ads_get_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/ad_accounts/{ad_account_id}/ads", OpenAPI.Servers.middleware(impl, ads_list_read, ads_list_validate, ads_list_invoke; optional_middlewares...))
    HTTP.register!(router, "PATCH", path_prefix * "/ad_accounts/{ad_account_id}/ads", OpenAPI.Servers.middleware(impl, ads_update_read, ads_update_validate, ads_update_invoke; optional_middlewares...))
    HTTP.register!(router, "POST", path_prefix * "/ad_accounts/{ad_account_id}/campaign_ad_preview", OpenAPI.Servers.middleware(impl, campaign_ad_preview_create_read, campaign_ad_preview_create_validate, campaign_ad_preview_create_invoke; optional_middlewares...))
    HTTP.register!(router, "DELETE", path_prefix * "/ad_accounts/{ad_account_id}/campaign_ad_preview", OpenAPI.Servers.middleware(impl, campaign_ad_preview_delete_read, campaign_ad_preview_delete_validate, campaign_ad_preview_delete_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/ad_accounts/{ad_account_id}/campaign_ad_preview", OpenAPI.Servers.middleware(impl, campaign_ad_preview_read_read, campaign_ad_preview_read_validate, campaign_ad_preview_read_invoke; optional_middlewares...))
    return router
end
